import{_ as a,o,c as t,a5 as r}from"./chunks/framework.kcd3e0J6.js";const i="/study/images/io/mapped-file-addresses.svg",s="/study/images/io/mapped-access-and-lifetime.svg",g=JSON.parse('{"title":"メモリマップドファイル — ファイルの範囲をアドレスへ対応させる","description":"","frontmatter":{"title":"メモリマップドファイル — ファイルの範囲をアドレスへ対応させる","study":{"source":"新規執筆","section":"reference","format":"article","status":"published","domain":"os","summary":"ファイルオフセットと仮想アドレスの対応、ビューの整列、ページフォルトによる待ち、ビューと参照の寿命を説明する。Windowsと.NETの読取り専用マッピングを中心に、書込み・COW・flushとの境界を区別する。","aliases":["メモリマップドファイル","memory-mapped file","file mapping","mmap","マッピング","ファイルビュー","CreateFileMapping","MapViewOfFile","UnmapViewOfFile","MemoryMappedFile","MemoryMappedViewAccessor","PointerOffset","allocation granularity"],"verification":"一次資料照合（2026-11-04）"}},"headers":[],"relativePath":"os/memory-mapped-files.md","filePath":"os/memory-mapped-files.md"}'),n={name:"os/memory-mapped-files.md"};function d(c,e,p,l,f,m){return o(),t("div",null,[...e[0]||(e[0]=[r(`<h1 id="メモリマップドファイル-—-ファイルの範囲をアドレスへ対応させる" tabindex="-1">メモリマップドファイル — ファイルの範囲をアドレスへ対応させる <a class="header-anchor" href="#メモリマップドファイル-—-ファイルの範囲をアドレスへ対応させる" aria-label="Permalink to &quot;メモリマップドファイル — ファイルの範囲をアドレスへ対応させる&quot;">​</a></h1><p><strong>メモリマップドファイル</strong>は、ファイルの内容と、プロセスの仮想アドレス空間の一部を対応付けて扱う仕組みです。対応する範囲を<strong>ビュー</strong>（view）と呼びます。通常の<code>ReadFile</code>ではアプリの受取バッファへ読み取りますが、マッピングではビューのアドレスを通じて内容へアクセスします。<a href="https://learn.microsoft.com/en-us/windows/win32/memory/file-mapping" target="_blank" rel="noreferrer">Microsoft: File Mapping</a></p><p>ここではWindowsの通常ファイルと、Windows版.NET 10の読取り専用ビューを中心に説明します。POSIXの<code>mmap</code>と同じAPI契約として扱いません。アドレス変換とページの基本は<a href="/study/os/virtual-memory.html">仮想メモリ</a>、通常のreadとキャッシュは<a href="/study/os/file-read-journey.html">ファイルを読む仕組み</a>を参照してください。</p><h2 id="ファイルの位置と、メモリの位置を区別する" tabindex="-1">ファイルの位置と、メモリの位置を区別する <a class="header-anchor" href="#ファイルの位置と、メモリの位置を区別する" aria-label="Permalink to &quot;ファイルの位置と、メモリの位置を区別する&quot;">​</a></h2><p><strong>ファイルオフセット</strong>は先頭から何byte目かを示す数です。<strong>仮想アドレス</strong>は、現在のプロセス内でメモリへアクセスするための場所です。同じファイルをマップし直しても、同じ仮想アドレスになる保証はありません。</p><p>例えば、ファイルのオフセット65536から13byteをマップし、返された先頭アドレスを<code>p</code>とします。このとき<code>p + 5</code>は、ファイルオフセット65541に対応します。65541はアドレスそのものではなく、<code>p</code>もディスク上の位置ではありません。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>対応するファイルオフセット = ビュー開始のファイルオフセット + ビュー内の位置</span></span>
<span class="line"><span>アクセスする仮想アドレス   = ビューの先頭アドレス             + ビュー内の位置</span></span></code></pre></div><p>この対応には範囲があります。計算が整数型に収まり、対象がファイルと要求ビューの有効範囲内にあることを確認します。OSがページ単位に丸めて管理していても、余分な部分までアプリの有効なデータとして読んでよい根拠にはしません。<a href="https://learn.microsoft.com/en-us/windows/win32/api/memoryapi/nf-memoryapi-mapviewoffile" target="_blank" rel="noreferrer">Microsoft: MapViewOfFile — offset and size</a></p><h2 id="windowsの割当粒度に合わせてビューを作る" tabindex="-1">Windowsの割当粒度に合わせてビューを作る <a class="header-anchor" href="#windowsの割当粒度に合わせてビューを作る" aria-label="Permalink to &quot;Windowsの割当粒度に合わせてビューを作る&quot;">​</a></h2><p>Win32の<code>MapViewOfFile</code>では、開始ファイルオフセットをシステムの<strong>割当粒度</strong>（allocation granularity）の倍数にします。<code>GetSystemInfo</code>が返す<code>dwAllocationGranularity</code>で取得する値です。<code>dwPageSize</code>はページ保護やコミットの粒度を表す別の値で、混同しません。<a href="https://learn.microsoft.com/en-us/windows/win32/api/sysinfoapi/ns-sysinfoapi-system_info" target="_blank" rel="noreferrer">Microsoft: SYSTEM_INFO</a></p><p>割当粒度を<code>G</code>、読みたい先頭を<code>offset</code>、必要な長さを<code>length</code>とすると、次のように前へ揃えます。ここではすべて非負の整数です。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>baseOffset = (offset / G) * G</span></span>
<span class="line"><span>delta      = offset - baseOffset</span></span>
<span class="line"><span>viewLength = delta + length</span></span></code></pre></div><p><code>G = 65536</code>の説明例で、<code>offset = G + 5</code>から8byteを読むなら、<code>baseOffset = G</code>、<code>delta = 5</code>、<code>viewLength = 13</code>です。ファイルのオフセット<code>G</code>から13byteをビューにし、その中の5〜12番を使います。65536はこの図の値であり、実践コードは実行時に<code>G</code>を取得します。<a href="https://learn.microsoft.com/en-us/windows/win32/memory/creating-a-file-view" target="_blank" rel="noreferrer">Microsoft: Creating a File View</a></p><figure class="study-figure"><img src="`+i+'" alt="割当粒度Gの倍数から13byteをマップし、ビュー内delta5から8byteを読む例。ファイルオフセットG+5、Win32のビュー内位置5、.NETの要求アクセサー内位置0を区別する。" width="760" height="1510"><figcaption><strong>ファイル内の位置、整列したビュー、目的範囲を分ける。</strong> 図のGは説明用の65536です。仮想アドレスの数値や物理RAM上の配置を決める図ではありません。<a href="/study/images/io/mapped-file-addresses.svg" target="_blank" rel="noopener noreferrer">ファイルとアドレスの対応図を拡大</a></figcaption></figure><h2 id="マップしただけで全内容がramへ届くわけではない" tabindex="-1">マップしただけで全内容がRAMへ届くわけではない <a class="header-anchor" href="#マップしただけで全内容がramへ届くわけではない" aria-label="Permalink to &quot;マップしただけで全内容がRAMへ届くわけではない&quot;">​</a></h2><p>ビューを作ることは、ファイルの全byteを事前に読み終えたという完了通知ではありません。通常のページングでは、アクセスしたページに必要な対応がなければ<strong>ページフォルト</strong>が起き、OSが処理します。</p><p>必要な内容がRAM内の共有ページやキャッシュにあれば、ストレージから新たに読まずに解決できる場合があります。Windowsの用語では、裏付け先からの読取りを必要としないものがソフトページフォルト、必要なものがハードページフォルトです。フォルトの回数だけで物理I/Oの回数は決まりません。<a href="https://learn.microsoft.com/en-us/windows/win32/memory/working-set" target="_blank" rel="noreferrer">Microsoft: Working Set</a></p><p>ストレージから内容を得る必要があれば、<strong>そのアドレスを読んだスレッドが待つことがあります。</strong> 通常のメモリ読取りに見える式の中で、I/O待ちが現れ得るわけです。ビューを作った後に別の部分を参照すれば、そこで新たに待つ可能性もあります。</p><p>したがってマッピングは、<a href="/study/os/asynchronous-file-io.html">非同期I/O</a>の要求・完了通知と同じ方式ではありません。「マップ済みだからメインスレッドで触っても待たない」「一度読んだから永久にRAMに残る」とは言えません。OSによる先読みやページの回収もあり、常駐状態は変化します。</p><p>また、<strong>マッピングの作成成功と、その後の読取り成功は別</strong>です。ファイルを支えるデバイスや接続の問題などで、アクセス時に<code>EXCEPTION_IN_PAGE_ERROR</code>が生じる場合があります。C++の通常の<code>catch (std::exception&amp;)</code>へ自動的に同じ形で届くものではなく、Windowsの構造化例外処理（SEH）の対象です。実践のC++例は、対象範囲内のこの例外だけを小さな読取り関数で区別します。故障を意図的に起こす教材ではありません。<a href="https://learn.microsoft.com/en-us/windows/win32/memory/reading-and-writing-from-a-file-view" target="_blank" rel="noreferrer">Microsoft: Reading and Writing From a File View</a></p><h2 id="win32のファイル・マッピングオブジェクト・ビュー" tabindex="-1">Win32のファイル・マッピングオブジェクト・ビュー <a class="header-anchor" href="#win32のファイル・マッピングオブジェクト・ビュー" aria-label="Permalink to &quot;Win32のファイル・マッピングオブジェクト・ビュー&quot;">​</a></h2><p>読取り専用の例では、三つの資源を区別します。</p><table tabindex="0"><thead><tr><th>資源</th><th>作る操作</th><th>役割と終了操作</th></tr></thead><tbody><tr><td>ファイルハンドル</td><td><code>CreateFileW</code></td><td>読取り元を開く。<code>CloseHandle</code>で閉じる</td></tr><tr><td>ファイルマッピングオブジェクト</td><td><code>CreateFileMappingW</code></td><td>ファイルとの対応を管理する。<code>CloseHandle</code>で閉じる</td></tr><tr><td>ビュー</td><td><code>MapViewOfFile</code></td><td>プロセス内でアクセスする範囲。<code>UnmapViewOfFile</code>で解除する</td></tr></tbody></table><p><code>CreateFileMappingW</code>自体はアプリが触れるビューの先頭ポインタを返しません。読取り専用なら、読取り権限のファイルから<code>PAGE_READONLY</code>のマッピングを作り、<code>FILE_MAP_READ</code>のビューを作ります。マッピングの権限とビューの権限には互換性が必要です。<a href="https://learn.microsoft.com/en-us/windows/win32/api/memoryapi/nf-memoryapi-createfilemappingw" target="_blank" rel="noreferrer">Microsoft: CreateFileMappingW</a></p><p><strong>ビュー内へのポインタ、参照、そこを指すspanは、ビューの寿命を延ばしません。</strong> 解除した後は使えません。所有者を保持して利用期間を結び付けるか、必要な内容を別の所有バッファへコピーします。実践では8byteを配列へコピーし、その配列だけを外へ返します。</p><p>ファイルやマッピングオブジェクトのハンドルを閉じることも、ビューの解除そのものではありません。Win32ではハンドルを閉じても残るビューがあるため、<code>CloseHandle</code>だけで後片付けが済むと考えません。実践はRAIIでビューを先に解除し、マッピングとファイルを閉じます。RAIIは、所有するC++オブジェクトの破棄に後片付けを結び付ける方法です。<a href="https://learn.microsoft.com/en-us/windows/win32/memory/closing-a-file-mapping-object" target="_blank" rel="noreferrer">Microsoft: Closing a File Mapping Object</a></p><figure class="study-figure"><img src="'+s+'" alt="マッピング後のアクセスがRAM内で解決する場合、ページフォルトで待つ場合、I/O例外となる場合を示し、参照利用終了からビュー解除、ハンドルの解放までを分けた概念図。" width="760" height="1510"><figcaption><strong>マップ済みでも、アクセス時の待ちと失敗を考える。</strong> ビューに依存する参照は解除前に使い終えます。物理I/Oの発生や待ち時間を実測した図ではありません。<a href="/study/images/io/mapped-access-and-lifetime.svg" target="_blank" rel="noopener noreferrer">アクセスと寿命の図を拡大</a></figcaption></figure><h2 id="c-のアクセサー内位置は、要求したビューから数える" tabindex="-1">C#のアクセサー内位置は、要求したビューから数える <a class="header-anchor" href="#c-のアクセサー内位置は、要求したビューから数える" aria-label="Permalink to &quot;C#のアクセサー内位置は、要求したビューから数える&quot;">​</a></h2><p><code>MemoryMappedFile.CreateFromFile</code>は既存のファイルからマッピングを作り、<code>CreateViewAccessor(offset, size, MemoryMappedFileAccess.Read)</code>は、その範囲を読めるアクセサーを作ります。アクセサーは、位置を指定して読み書きするためのオブジェクトです。<a href="https://learn.microsoft.com/en-us/dotnet/api/system.io.memorymappedfiles.memorymappedfile.createfromfile?view=net-10.0" target="_blank" rel="noreferrer">Microsoft: CreateFromFile</a>、<a href="https://learn.microsoft.com/en-us/dotnet/api/system.io.memorymappedfiles.memorymappedfile.createviewaccessor?view=net-10.0" target="_blank" rel="noreferrer">CreateViewAccessor</a></p><p>実践では<code>offset = G + 5</code>、<code>size = 8</code>を直接渡し、<code>ReadArray&lt;byte&gt;(position: 0, ...)</code>で読みます。ここで0は、<strong>要求したアクセサーの先頭</strong>です。Win32例の生ポインタに足す<code>delta = 5</code>を、アクセサーの位置へもう一度足しません。<a href="https://learn.microsoft.com/en-us/dotnet/api/system.io.unmanagedmemoryaccessor.readarray?view=net-10.0" target="_blank" rel="noreferrer">Microsoft: ReadArray</a></p><p>Windows版.NET v10.0.0の公開実装では、内部で開始位置を割当粒度へ揃え、先頭の余分な部分を隠します。今回のWindows実測では、その差を表す<code>PointerOffset</code>は5でした。要求したファイルオフセット65541、アクセサー内の位置0とは別の数です。この内部整列を全OSの実装へ一般化しません。<a href="https://github.com/dotnet/runtime/blob/v10.0.0/src/libraries/System.IO.MemoryMappedFiles/src/System/IO/MemoryMappedFiles/MemoryMappedView.Windows.cs" target="_blank" rel="noreferrer">.NET: Windowsのビュー作成</a>、<a href="https://github.com/dotnet/runtime/blob/v10.0.0/src/libraries/System.IO.MemoryMappedFiles/src/System/IO/MemoryMappedFiles/MemoryMappedViewAccessor.cs" target="_blank" rel="noreferrer">アクセサーへのオフセットの適用</a></p><p><code>using</code>でアクセサー、マッピング、ストリームの順に破棄します。<code>leaveOpen: true</code>はマッピングの破棄後も元のストリームを残す指定であり、元の所有者による破棄が不要になる指定ではありません。実践はストリームも別の<code>using</code>で管理します。</p><h2 id="読取り専用・cow・書込み・永続化は別の契約" tabindex="-1">読取り専用・COW・書込み・永続化は別の契約 <a class="header-anchor" href="#読取り専用・cow・書込み・永続化は別の契約" aria-label="Permalink to &quot;読取り専用・COW・書込み・永続化は別の契約&quot;">​</a></h2><p>読取り専用は「このビューから書かない」というアクセス権です。ファイル内容が永遠に変わらないことや、作成時点のスナップショットを意味しません。</p><table tabindex="0"><thead><tr><th>方式</th><th>書込みの扱い</th></tr></thead><tbody><tr><td>読取り専用</td><td>ビューへの書込みは許可されない</td></tr><tr><td>コピーオンライト（COW）</td><td>書いたページをそのプロセス用に分ける。元ファイルへは書き戻さない</td></tr><tr><td>書込み可能なビュー</td><td>ファイルへ反映する変更として扱う。同期と保存の条件が必要</td></tr></tbody></table><p>Windowsの<code>FILE_MAP_COPY</code>はCOWです。全ページが変更され得るため、ビュー全体についてコミット量が計上される点も含め、通常の読取り専用とは区別します。<a href="https://learn.microsoft.com/en-us/windows/win32/api/memoryapi/nf-memoryapi-mapviewoffile" target="_blank" rel="noreferrer">Microsoft: MapViewOfFile — access flags</a></p><p>書込み可能なビューへ書いても、その瞬間にストレージへの保存が完了するわけではありません。<code>FlushViewOfFile</code>だけではファイルのメタデータや、機器内部のキャッシュまでの永続化を保証しません。Windowsの資料は、対象の変更とメタデータをディスクへ書く場合に<code>FlushViewOfFile</code>に続けて<code>FlushFileBuffers</code>を呼ぶ手順を示しています。これは複数の変更の原子性や、破損しない保存形式まで保証する手順ではありません。ネットワーク越しの保存にも別の条件があります。<a href="https://learn.microsoft.com/en-us/windows/win32/api/memoryapi/nf-memoryapi-flushviewoffile" target="_blank" rel="noreferrer">Microsoft: FlushViewOfFile</a></p><p>今回の実践は読取り専用で、COW、共有書込み、flush、障害時の永続性は検証しません。</p><h2 id="ファイル変更と、ゲームで選ぶ条件" tabindex="-1">ファイル変更と、ゲームで選ぶ条件 <a class="header-anchor" href="#ファイル変更と、ゲームで選ぶ条件" aria-label="Permalink to &quot;ファイル変更と、ゲームで選ぶ条件&quot;">​</a></h2><p>ビューが有効でも、別の処理による変更と同時に読んでよいとは限りません。読取り側が複数フィールドの途中状態を見る問題は、マッピングだけでは解決しません。通常の<code>ReadFile</code>・<code>WriteFile</code>とマップしたビューの一貫性も、一律に保証されません。実践は自己所有の固定ファイルを使い、読取り中に変更しません。<a href="https://learn.microsoft.com/en-us/windows/win32/api/memoryapi/nf-memoryapi-mapviewoffile" target="_blank" rel="noreferrer">Microsoft: MapViewOfFile — coherency</a></p><p>切詰めも、マップしたまま安全に長さだけ変えられる操作とは扱いません。Windowsの<code>SetEndOfFile</code>には、先に全ビューを解除し、マッピングオブジェクトを閉じる条件があります。他OSの切詰め後の挙動を、そのままWindowsの説明へ移しません。<a href="https://learn.microsoft.com/en-us/windows/win32/api/fileapi/nf-fileapi-setendoffile" target="_blank" rel="noreferrer">Microsoft: SetEndOfFile</a></p><p>ゲームでは、大きな読取り専用データの一部を参照する用途などで検討できます。ただし、明示的なreadの削減と、ページフォルト、仮想アドレスの消費、ビューの寿命管理を合わせて判断します。今回のように配列へコピーするコードなら、そのコピーも残ります。<strong>必ず高速になる方式でも、必ずコピーがゼロになる方式でもありません。</strong></p><p>ファイル内へ実行時の生ポインタを保存せず、オフセットなどで参照を表します。byteをC++の構造体へそのまま重ねる設計も、アラインメント・型の寿命・形式の版・byte順を別に検討する必要があります。<a href="/study/data/integer-bits-and-bytes.html">整数とバイト列</a>の区別も使います。</p><p>マッピングは<a href="/study/game/asset-loading.html">ゲームのアセットロード設計</a>で選ぶ読取り手段の一つです。圧縮データの展開やデコード、GPUへの転送、利用可能化まで自動で済ませるものではありません。</p><h2 id="実践記事" tabindex="-1">実践記事 <a class="header-anchor" href="#実践記事" aria-label="Permalink to &quot;実践記事&quot;">​</a></h2><p><a href="/study/practice/io/mapped-file-observation.html">通常のreadと読取り専用マッピングを比較する</a>では、既知の8byteを両方式で読み、Win32の整列と.NETの位置指定を確かめます。作った直後の小さなファイルなので、全内容がいつRAMへ届いたか、ストレージI/Oの有無、速度の優劣はこの実験から結論しません。</p>',46)])])}const w=a(n,[["render",d]]);export{g as __pageData,w as default};
